/*1. Sorting a List of Employee Objects*/
import java.util.*;

class Employee {
    String name;
    int age;
    double salary;

    public Employee(String name, int age, double salary) {
        this.name = name;
        this.age = age;
        this.salary = salary;
    }

    @Override
    public String toString() {
        return name + " | Age: " + age + " | Salary: " + salary;
    }
}

public class EmployeeSort {
    public static void main(String[] args) {
        List<Employee> employees = new ArrayList<>(Arrays.asList(
            new Employee("Alice", 30, 50000),
            new Employee("Bob", 25, 60000),
            new Employee("Charlie", 35, 55000)
        ));

        // Sort by name
        employees.sort(Comparator.comparing(emp -> emp.name));
        System.out.println("Sorted by Name: " + employees);

        // Sort by age
        employees.sort(Comparator.comparingInt(emp -> emp.age));
        System.out.println("Sorted by Age: " + employees);

        // Sort by salary
        employees.sort(Comparator.comparingDouble(emp -> emp.salary));
        System.out.println("Sorted by Salary: " + employees);
    }
}


/*2. Filtering and Sorting Students using Streams */
import java.util.*;
import java.util.stream.Collectors;

class Student {
    String name;
    double marks;

    public Student(String name, double marks) {
        this.name = name;
        this.marks = marks;
    }

    public double getMarks() {
        return marks;
    }

    @Override
    public String toString() {
        return name + " | Marks: " + marks;
    }
}

public class StudentFilter {
    public static void main(String[] args) {
        List<Student> students = Arrays.asList(
            new Student("John", 80),
            new Student("Alice", 90),
            new Student("Bob", 70),
            new Student("Eve", 85)
        );

        // Filter students with marks > 75, sort in descending order, and collect names
        List<String> topStudents = students.stream()
            .filter(s -> s.getMarks() > 75)
            .sorted((s1, s2) -> Double.compare(s2.getMarks(), s1.getMarks()))
            .map(s -> s.name)
            .collect(Collectors.toList());

        System.out.println("Top Students: " + topStudents);
    }
}
